package lr2touch;
import java.nio.file.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import org.objectweb.asm.*;
public class BattleVerify {
 static void check(boolean v,String m){if(!v)throw new AssertionError(m);}
 static void waitFor(java.util.function.BooleanSupplier v,long ms)throws Exception{long end=System.nanoTime()+ms*1_000_000;while(!v.getAsBoolean()&&System.nanoTime()<end)Thread.sleep(10);check(v.getAsBoolean(),"Timed out");}
 static class Fake implements AutoCloseable {BattleWire wire;BattleClock clock=new BattleClock();ScheduledExecutorService timer=Executors.newSingleThreadScheduledExecutor();volatile int slot;volatile String phase="",id="",manifest="same-assets";volatile boolean abort,skipArm;volatile long target;Fake(BattleServer s,String name,String pin)throws Exception{wire=new BattleWire(new Socket("127.0.0.1",s.listener.getLocalPort()),v->{switch(v[0]){case "WELCOME":slot=Integer.parseInt(v[1]);break;case "PONG":clock.accept(Long.parseLong(v[1]),Long.parseLong(v[2]),Long.parseLong(v[3]),System.nanoTime());break;case "STATE":phase=v[1];break;case "CHECK":id=v[1];abort=false;wire.send("CHECKED",id,manifest,v[3]);break;case "LOAD":wire.send("READY",id,"1000","Example song","Example artist","Sample table");break;case "ARM":target=Long.parseLong(v[2]);if(!skipArm)wire.send("ARMED",id);break;case "COMMIT":wire.send("COMMITTED",id);break;case "ABORT":abort=true;break;}},()->{});wire.start();wire.send("HELLO","1",pin,name,"same-build");timer.scheduleWithFixedDelay(()->{wire.send("PING",""+System.nanoTime());wire.send("SYNC",""+clock.rtt,""+clock.uncertainty,""+clock.count);},0,100,TimeUnit.MILLISECONDS);}void offer(){wire.send("OFFER","a".repeat(64),"Chosen song","Artist","Table","0");}public void close(){timer.shutdownNow();wire.close();}}
 public static void main(String[] args)throws Exception{
  BattleClock c=new BattleClock();for(int i=0;i<10;i++){long t=System.nanoTime();c.accept(t, t+2_000_000_000L+2_000_000,t+2_000_000_000L+2_100_000,t+4_100_000);}check(c.offset==2_000_000_000L&&c.rtt==4_000_000,"clock estimate");
  Path temp=Files.createTempDirectory(Paths.get("work"),"battle-assets-");Files.writeString(temp.resolve("chart.bms"),"#TITLE TEST");Files.writeString(temp.resolve("sound.wav"),"sample");String one=BattleClient.manifest(temp,()->true);Files.writeString(temp.resolve("sound.wav"),"changed");check(!one.equals(BattleClient.manifest(temp,()->true)),"asset mismatch");
  byte[] original=ClassLoader.getSystemResourceAsStream("bms/player/beatoraja/play/BMSPlayer.class").readAllBytes();byte[] modified=new BattleHooks().transform(null,"bms/player/beatoraja/play/BMSPlayer",null,null,original);check(modified!=null&&BattleHooks.installed,"installed game hook");ClassLoader loader=new ClassLoader(BattleVerify.class.getClassLoader()){Class<?> load(){return defineClass("bms.player.beatoraja.play.BMSPlayer",modified,0,modified.length);}};var method=loader.getClass().getDeclaredMethod("load");method.setAccessible(true);((Class<?>)method.invoke(loader)).getDeclaredMethods();
  BattleClient client=GameVerify.allocate(BattleClient.class);BattleClient.active=client;BattleClient.Round r=new BattleClient.Round("x","a".repeat(64),"0");client.round=r;r.loaded=true;r.navigated=true;Object player=new Object();check(BattleClient.gate(1000,player)==Integer.MAX_VALUE&&r.ready,"hold until host");r.committed=true;r.deadline=System.nanoTime()+1_000_000_000;client.lastServer=System.nanoTime();check(BattleClient.gate(1000,player)==Integer.MAX_VALUE,"no early start");r.deadline=System.nanoTime()-1_000_000;check(BattleClient.gate(1000,player)==-1&&r.started,"scheduled release");check(BattleClient.gate(1000,new Object())==1000,"subsequent solo chart unaffected");r.started=false;r.deadline=System.nanoTime()-100_000_000;check(BattleClient.gate(1000,player)==Integer.MAX_VALUE&&!r.error.isEmpty(),"late release rejected");BattleClient.active=null;
  Path overlay=Paths.get("work/battle-release/Subscreen/battle-overlay");try(BattleServer server=new BattleServer(0,0,"123456",overlay);Fake p1=new Fake(server,"Player One","123456");Fake p2=new Fake(server,"Player Two","123456")){
   waitFor(()->p1.slot>0&&p2.slot>0&&server.both(),3000);waitFor(()->server.clockGood(server.peers[0])&&server.clockGood(server.peers[1]),5000);
   try(Fake extra=new Fake(server,"Extra","123456")){waitFor(()->extra.wire.closed,3000);check(extra.slot==0,"third player rejected");}
   p1.offer();p2.offer();waitFor(()->!server.peers[0].offer.isEmpty()&&!server.peers[1].offer.isEmpty(),1000);
   p2.manifest="different";check(server.select(0),"select chart");waitFor(()->server.phase.equals("CANCELLED"),3000);check(!server.startRound(),"mismatch cannot start");
   p2.manifest="same-assets";check(server.select(1),"second player's choice");waitFor(()->server.phase.equals("READY"),3000);check(!server.startRound(),"explicit sync confirmation required");check(server.checkSync()&&server.startRound(),"start ready match");waitFor(()->server.phase.equals("COUNTDOWN"),3000);check(p1.target==p2.target,"shared server deadline");waitFor(()->server.phase.equals("PLAYING"),7000);
   p1.wire.send("SCORE",p1.id,"1234",""+p1.target,"FINISHED");p2.wire.send("SCORE",p2.id,"1200",""+(p2.target+2_000_000),"FINISHED");waitFor(()->server.phase.equals("FINISHED"),1500);String state=new String(new URL("http://127.0.0.1:"+server.http.port()+"/state.json").openStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);check(state.contains("\"difference\":34")&&state.contains("Example song"),"OBS scores and metadata");
   p2.skipArm=true;check(server.select(0),"new round");waitFor(()->server.phase.equals("READY"),3000);check(server.checkSync()&&server.startRound(),"arm failure scenario");waitFor(()->server.phase.equals("CANCELLED"),6500);check(!server.phase.equals("PLAYING"),"missing arm ack cancels");
   check(server.select(0),"disconnect scenario");waitFor(()->server.phase.equals("READY"),3000);p2.close();waitFor(()->server.phase.equals("CANCELLED"),2000);
  }
  try(BattleServer server=new BattleServer(0,-1,"123456",overlay);Fake wrong=new Fake(server,"Bad PIN","999999")){waitFor(()->wrong.wire.closed,3000);check(!server.both(),"wrong room rejected");}
  System.out.println("PASS: installed READY hook verification, gate holds/late refusal, clock math, asset mismatch, real TCP two-player selection/prepare/start, explicit clock check, shared deadline, EX/OBS JSON, third/wrong-code rejection, missing ACK and disconnect cancellation");
 }
}
